import gzip,glob,re
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:2]+sorted(glob.glob('studies/data/raw/*series_matrix*'))[3:]:
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        for m in set(re.findall(r'[^"\t]{0,100}(?:tamox|OHT|nM|µM|uM|hydroxy|ng/ml)[^"\t]{0,100}',l,re.I)): print(l[:25],'|',m)

